CREATE TABLE IF NOT EXISTS "User" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" TEXT NOT NULL,
	"email" TEXT NOT NULL UNIQUE,
	"password" TEXT NOT NULL,
	"role" TEXT NOT NULL DEFAULT 'student' CHECK(role IN ('student', 'instructor', 'admin')),
	"created_at" TIMESTAMPTZ NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "Course" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"language_id" INTEGER NOT NULL,
	"owner_id" INTEGER,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "Enrollment" (
	"user_id" INTEGER NOT NULL,
	"course_id" INTEGER NOT NULL,
	"is_instructor" BOOLEAN NOT NULL DEFAULT FALSE,
	PRIMARY KEY("user_id", "course_id")
);

COMMENT ON TABLE "Enrollment" IS 'This doesn''t refer to their overall user permissions role, but rather their permissions for this specific course. The idea is that an owner of a course could allow a TA etc to do instructor tasks for this specific course';

CREATE TABLE IF NOT EXISTS "Language" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" TEXT NOT NULL UNIQUE,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "Difficulty" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" TEXT NOT NULL UNIQUE,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "Answer" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" TEXT NOT NULL UNIQUE,
	"image" BYTEA NOT NULL,
	"creator_id" INTEGER,
	"created_at" TIMESTAMPTZ NOT NULL,
	"updated_at" TIMESTAMPTZ NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "Clue" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"audio" BYTEA NOT NULL,
	"difficulty_id" INTEGER NOT NULL,
	"language_id" INTEGER NOT NULL,
	"answer_id" INTEGER NOT NULL,
	"creator_id" INTEGER,
	"created_at" TIMESTAMPTZ NOT NULL,
	"updated_at" TIMESTAMPTZ NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "Game" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"num_items" INTEGER NOT NULL,
	"difficulty_id" INTEGER NOT NULL,
	"language_id" INTEGER NOT NULL,
	"due_at" TIMESTAMPTZ,
	"course_id" INTEGER,
	"creator_id" INTEGER,
	"created_at" TIMESTAMPTZ NOT NULL,
	"updated_at" TIMESTAMPTZ NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "ClueUsage" (
	"game_id" INTEGER NOT NULL,
	"clue_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	PRIMARY KEY("game_id", "clue_id")
);

CREATE TABLE IF NOT EXISTS "Play" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"score" NUMERIC,
	"started_at" TIMESTAMPTZ NOT NULL,
	"user_id" INTEGER NOT NULL,
	"game_id" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

